import{_ as s,c as a,o as t,b0 as e}from"./chunks/framework.CLL9SSSf.js";const n="/linux-driver-docs/assets/image-20250121105044537.Dh-pOb_p.png",l="/linux-driver-docs/assets/image-20250121105204784.Cv_4my63.png",r="/linux-driver-docs/assets/image-20250122095804419.CorEwr3j.png",p="/linux-driver-docs/assets/image-20250122100058803.Dm_9pdeJ.png",d="/linux-driver-docs/assets/image-20250122100356113.DIpLpSIn.png",v=JSON.parse('{"title":"LV020-原子操作","description":null,"frontmatter":{"title":"LV020-原子操作","date":"2026-01-19T15:23:25.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/drv-base/concur-race/126d2d3486c53b72ff0c0091","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-19T15:23:25.951Z","fulluuid":"2ff0c009148c400faf39cc98acf1c95a","useduuid":"2ff0c0091"}},"headers":[],"relativePath":"sdoc/drv-base/concur-race/126d2d3486c53b72ff0c0091.md","filePath":"sdoc/05-设备驱动基础/20-并发与竞争/LV020-原子操作.md","lastUpdated":1769002717000}'),h={name:"sdoc/drv-base/concur-race/126d2d3486c53b72ff0c0091.md"};function o(c,i,k,u,m,b){return t(),a("div",null,[...i[0]||(i[0]=[e(`<h1 id="lv020-原子操作" tabindex="-1">LV020-原子操作 <a class="header-anchor" href="#lv020-原子操作" aria-label="Permalink to &quot;LV020-原子操作&quot;">​</a></h1><h2 id="一、原子操作简介" tabindex="-1">一、原子操作简介 <a class="header-anchor" href="#一、原子操作简介" aria-label="Permalink to &quot;一、原子操作简介&quot;">​</a></h2><p>“原子” 是化学世界中不可再分的最小微粒， 一切物质都由原子组成。 在 Linux 内核中的原子操作可以理解为“不可被拆分的操作” ， 就是不能被更高等级中断抢夺优先的操作。</p><p>一般原子操作用于变量或者位操作。假如现在要对无符号整形变量 a 赋值，值为 3，对于 C 语言来讲很简单，直接就是：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>但是 C 语言要先编译为成汇编指令， ARM 架构不支持直接对寄存器进行读写操作，比如要借助寄存器 R0、 R1 等来完成赋值操作。假设变量 a 的地址为 0X3000000，“a = 3”这一行 C 语言可能会被编译为如下所示的汇编代码：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ldr r0, =0X30000000 /* 变量 a 地址 */</span></span>
<span class="line"><span>ldr r1, = 3         /* 要写入的值 */</span></span>
<span class="line"><span>str r1, [r0]        /* 将 3 写入到 a 变量中 */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>只是一个简单的举例说明，实际的结果要比示例代码复杂的多。从上述代码可以看出， C 语言里面简简单单的一句“a = 3”，编译成汇编文件以后变成了 3 句，那么程序在执行的时候肯定是按照汇编语句一条一条的执行。假设现在线程 A 要向 a 变量写入 10 这个值，而线程 B 也要向 a 变量写入 20 这个值，我们理想中的执行顺序如图所示：</p><img src="`+n+'" alt="image-20250121105044537" style="zoom:50%;"><p>按照上图所示的流程，确实可以实现线程 A 将 a 变量设置为 10，线程 B 将 a 变量设置为 20。但是实际上的执行流程可能如下所示：</p><img src="'+l+`" alt="image-20250121105204784" style="zoom:50%;"><p>按照图这个图所示的流程，线程 A 最终将变量 a 设置为了 20，而并不是要求的 10！线程 B 没有问题。这就是一个最简单的设置变量值的并发与竞争的例子，要解决这个问题就 <strong>要保证那三行汇编指令作为一个整体运行，也就是作为一个原子存在</strong>。</p><h2 id="二、相关数据结构与-api" tabindex="-1">二、相关数据结构与 API <a class="header-anchor" href="#二、相关数据结构与-api" aria-label="Permalink to &quot;二、相关数据结构与 API&quot;">​</a></h2><p>Linux 内核提供了一组原子操作 API 函数来完成此功能， Linux 内核提供了两组原子操作 API 函数，一组是对整形变量进行操作的，一组是对位进行操作的，我们接下来看一下这些 API 函数和相关的数据结构。</p><h3 id="_1-atomic-t" tabindex="-1">1. <a href="https://elixir.bootlin.com/linux/v4.19.71/source/include/linux/types.h#L178" target="_blank" rel="noreferrer">atomic_t</a> <a class="header-anchor" href="#_1-atomic-t" aria-label="Permalink to &quot;1. [atomic_t](https://elixir.bootlin.com/linux/v4.19.71/source/include/linux/types.h#L178)&quot;">​</a></h3><p>在 Linux 内核中使用 <a href="https://elixir.bootlin.com/linux/v4.19.71/source/include/linux/types.h#L178" target="_blank" rel="noreferrer">atomic_t</a> 和 <a href="https://elixir.bootlin.com/linux/v4.19.71/source/include/linux/types.h#L181" target="_blank" rel="noreferrer">atomic64_t</a> 结构体分别来完成 32 位系统和 64 位系统的 <strong>整形数据原子操作</strong>， 两个结构体定义在 <a href="https://elixir.bootlin.com/linux/v4.19.71/source/include/linux/types.h#L181" target="_blank" rel="noreferrer">types.h - include/linux/types.h</a> 文件中</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typedef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> counter;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">atomic_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#ifdef</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> CONFIG_64BIT</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typedef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	long</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> counter;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">atomic64_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#endif</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="_2-原子整形操作-api" tabindex="-1">2. 原子整形操作 API <a class="header-anchor" href="#_2-原子整形操作-api" aria-label="Permalink to &quot;2. 原子整形操作 API&quot;">​</a></h3><p>如果要使用原子操作 API 函数，首先要先定义一个 atomic_t 的变量，如下所示 ：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">atomic_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 定义 a</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>也可以在定义原子变量的时候给原子变量赋初值，如下所示 :</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">atomic_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ATOMIC_INIT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> //定义原子变量 b 并赋初值为 0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>原子变量有了，接下来就是对原子变量进行操作，比如读、写、增加、减少等等， Linux 内核提供了大量的原子操作 API 函数，其实这些大部分都是宏：</p><table tabindex="0"><thead><tr><th>函数</th><th>描述</th></tr></thead><tbody><tr><td>ATOMIC_INIT(int i)</td><td>定义原子变量的时候对其初始化， 赋值为 i</td></tr><tr><td>int atomic_read(atomic_t *v)</td><td>读取 v 的值， 并且返回。</td></tr><tr><td>void atomic_set(atomic_t *v, int i)</td><td>向原子变量 v 写入 i 值。</td></tr><tr><td>void atomic_add(int i, atomic_t *v)</td><td>原子变量 v 加上 i 值。</td></tr><tr><td>void atomic_sub(int i, atomic_t *v)</td><td>原子变量 v 减去 i 值。</td></tr><tr><td>void atomic_inc(atomic_t *v)</td><td>原子变量 v 加 1</td></tr><tr><td>void atomic_dec(atomic_t *v)</td><td>原子变量 v 减 1</td></tr><tr><td>int atomic_dec_return(atomic_t *v)</td><td>原子变量 v 减 1， 并返回 v 的值。</td></tr><tr><td>int atomic_inc_return(atomic_t *v)</td><td>原子变量 v 加 1， 并返回 v 的值。</td></tr><tr><td>int atomic_sub_and_test(int i, atomic_t *v)</td><td>原子变量 v 减 i， 如果结果为 0 就返回真， 否则返回假</td></tr><tr><td>int atomic_dec_and_test(atomic_t *v)</td><td>原子变量 v 减 1， 如果结果为 0 就返回真， 否则返回假</td></tr><tr><td>int atomic_inc_and_test(atomic_t *v)</td><td>原子变量 v 加 1， 如果结果为 0 就返回真， 否则返回假</td></tr><tr><td>int atomic_add_negative(int i, atomic_t *v)</td><td>原子变量 v 加 i， 如果结果为负就返回真， 否则返回</td></tr></tbody></table><blockquote><p>这些都分散定义在这些头文件，它们是：</p><p><a href="https://elixir.bootlin.com/linux/v4.19.71/source/include/linux/atomic.h" target="_blank" rel="noreferrer">atomic.h - include/linux/atomic.h</a></p><p><a href="https://elixir.bootlin.com/linux/v4.19.71/source/include/asm-generic/atomic.h" target="_blank" rel="noreferrer">atomic.h - include/asm-generic/atomic.h</a></p></blockquote><p>相应的也提供了 64 位原子变量的操作 API 函数，这里我们就不详细了解，和上表中的 API 函数有用法一样，只是将“atomic_”前缀换为“atomic64_”，将 int 换为 long long。如果使用的是 64 位的 SOC，那么就要使用 64 位的原子操作函数。原子变量和相应的 API 函数使用起来很简单，参考如下:</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">atomic_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> v </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ATOMIC_INIT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> /* 定义并初始化原子变零 v = 0 */</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">atomic_set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">v</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          /* 设置 v = 10 */</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">atomic_read</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">v</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             /* 读取 v 的值，肯定是 10 */</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">atomic_inc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">v</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              /* v 的值加 1， v = 11 */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="_3-原子位操作-api" tabindex="-1">3. 原子位操作 API <a class="header-anchor" href="#_3-原子位操作-api" aria-label="Permalink to &quot;3. 原子位操作 API&quot;">​</a></h3><p>位操作也是很常用的操作， Linux 内核也提供了一系列的原子位操作 API 函数，只不过原子位操作不像原子整形变量那样有个 atomic_t 的数据结构，原子位操作是直接对内存进行操作， API 函数如下：</p><table tabindex="0"><thead><tr><th>函数</th><th>描述</th></tr></thead><tbody><tr><td>void set_bit(int nr, void *p)</td><td>将 p 地址的第 nr 位置 1。</td></tr><tr><td>void clear_bit(int nr, void *p)</td><td>将 p 地址的第 nr 位清零。</td></tr><tr><td>void change_bit(int nr, void *p)</td><td>将 p 地址的第 nr 位进行翻转。</td></tr><tr><td>int test_bit(int nr, void *p)</td><td>获取 p 地址的第 nr 位的值。</td></tr><tr><td>int test_and_set_bit(int nr, void *p)</td><td>将 p 地址的第 nr 位置 1，并且返回 nr 位原来的值。</td></tr><tr><td>int test_and_clear_bit(int nr, void *p)</td><td>将 p 地址的第 nr 位清零，并且返回 nr 位原来的值。</td></tr><tr><td>int test_and_change_bit(int nr, void *p)</td><td>将 p 地址的第 nr 位翻转，并且返回 nr 位原来的值。</td></tr></tbody></table><blockquote><p>Tips：</p><p><a href="https://elixir.bootlin.com/linux/v4.19.71/source/include/asm-generic/bitops/atomic.h#L14" target="_blank" rel="noreferrer">atomic.h - include/asm-generic/bitops/atomic.h</a></p><p><a href="https://elixir.bootlin.com/linux/v4.19.71/source/include/asm-generic/bitops/non-atomic.h#L104" target="_blank" rel="noreferrer">non-atomic.h - include/asm-generic/bitops/non-atomic.h</a></p></blockquote><h2 id="三、原子操作-demo" tabindex="-1">三、原子操作 demo <a class="header-anchor" href="#三、原子操作-demo" aria-label="Permalink to &quot;三、原子操作 demo&quot;">​</a></h2><h3 id="_1-demo-源码" tabindex="-1">1. demo 源码 <a class="header-anchor" href="#_1-demo-源码" aria-label="Permalink to &quot;1. demo 源码&quot;">​</a></h3><p>在 xxx_open()函数和 xxx_release()函数中加入原子整形变量 v 的赋值代码， 并且在 open()函数中加入原子整形变量 v 的判断代码， 从而实现同一时间内只允许一个应用打开该设备节点， 以此来防止共享资源竞争的产生。</p><p><a href="https://gitee.com/linux-dev-org/imx6ull-driver-demo/tree/main/07_concurrency/03_atomic" target="_blank" rel="noreferrer">07_concurrency/03_atomic</a></p><h3 id="_2-开发板验证" tabindex="-1">2. 开发板验证 <a class="header-anchor" href="#_2-开发板验证" aria-label="Permalink to &quot;2. 开发板验证&quot;">​</a></h3><p>我们将编译得到的 sdriver_demo.ko、app_demo.out 拷贝到开发板。</p><ul><li>（1）加载驱动</li></ul><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">insmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sdriver_demo.ko</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><img src="`+r+'" alt="image-20250122095804419"><ul><li>（2）1 个应用程序访问 设备节点</li></ul><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./app_demo.out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/sdevchr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sumu1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><img src="'+p+`" alt="image-20250122100058803"><p>在 open 的时候，原子变量变为 0，在 release 的时候，原子变量的值恢复到 1。</p><ul><li>（3）2 个应用程序访问 设备节点</li></ul><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./app_demo.out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/sdevchr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sumu1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./app_demo.out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/sdevchr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sumu2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><img src="`+d+'" alt="image-20250122100356113"><p>可以看到应用程序在打开第二次 /dev/sdevchr 文件的时候， 出现了“can&#39;t open file /dev/sdevchr !”打印， 证明文件打开失败， 只有在第一个应用关闭相应的文件之后， 下一个应用才能打开， 通过限制同一时间内设备访问数量， 来对共享资源进行保护。</p><blockquote><p>参考资料：</p><p><a href="https://blog.csdn.net/xhjcehust/article/details/26132167" target="_blank" rel="noreferrer">自旋锁在抢占(或非抢占)单核和多核中的作用_多核系统中, 任务可以通过自旋锁或者中断的方式独占 cpu-CSDN 博客</a></p></blockquote>',49)])])}const _=s(h,[["render",o]]);export{v as __pageData,_ as default};
